            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Aslını gizleyemez insan giydiği kaftanlarla, Bilmez ama kendini kandırır; söylediği yalanlarla…", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Âtiyi karanlık görerek azmi bırakmak, alçak bir ölüm varsa, emînim, budur ancak.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Vurulmuş tertemiz alnından, uzanmış yatıyor, bir hilâl uğruna yâ Rab, ne güneşler batıyor.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Kuzum, ayıp mı çalışmak, günah mı yük taşımak? Ayıp: Dilencilik, işlerken el, yürürken ayak.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Allah bu millete bir daha İstiklal Marşı yazdırmasın.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Enseden arslan kesilmek, cebheden yaltak kedi.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Zulmü alkışlayamam, zalimi asla sevemem, gelenin keyfi için geçmişe kalkıp sövemem.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Camiler, milletin düşüncelerini aydınlatmak için en uygun yerlerdir!", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Şu boğaz harbi nedir? Var mı ki dünyada eşi? Yükleniyor en kesif orduların dördü beşi, Tepeden yol bularak geçmek için Marmara'ya, Kim bilir kaç donanmayla sarılmış ufacık karaya.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Ne hayasızca tahaşşut ki ufuklar kapalı! Nerede? Gösterdiği vahşetle 'bu bir Avrupalı' Dedirir - Yırtıcı, his yoksulu, sırtlan kümesi.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Eski dünya, yeni dünya, bütün akvam-ı beşer, Kaynıyor kum gibi, tufan gibi, mahşer mahşer, Yedi iklimi cihanın duruyor karşısında, Ostralya ile beraber bakıyorsun: Kanada!", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Çehreler başka, lisanlar, deriler rengarenk; Sade bir hadise var ortada: Vahşetler denk Kimi Hindû, kimi yamyam, kimi bilmem ne belâ...", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Ya Rab, bu uğursuz gecenin yok mu sabahı? Mahşerde mi yoksa biçarelerin felahı?", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Nur istiyoruz... Sen bize yangın veriyorsun! Yandık diyoruz... Boğmaya kan gönderiyorsun!", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Esmezse eğer bir ezeli nefha yakında, Ya Rab... O cehennemle bu tufan arasında.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Toprak kesilip, kum kesilip alemi İslam; Hep fışkıracak yerlerin altındaki esnam.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Geçmişten adam hisse kaparmış... Ne masal şey! Beş bin senelik kıssa yarım hisse mi verdi? \"Tarih\"i \"tekerrür\" diye tarif ediyorlar; Hiç ibret alınsaydı, tekerrür mü ederdi?", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Türk Arapsız yaşayamaz; kim ki yaşar der, delidir. Arabın Türk, hem sağ gözüdür, hem sağ elidir. Veriniz başbaşa, zira sonu hüsranı mübin.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Ne irfandır veren ahlaka yükseklik ne vicdandır. Fazilet hissi insanlarda Allah korkusundandır.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Yüreklerden çekilmiş farz edilsin havfı Yezdanın Ne irfanın kalır tesiri katiyyen, ne vicdanın.", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Ha bu din, iman, takva; inan ki hepsi yalan Sen onları kendine taptırırsın vesselam!", Author = "Mehmet Akif Ersoy" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Mehmet_Akif_Ersoy", Text = "Derdin, davan sadece, hep nefsi saltanatın Şimdilik putu sensin, tapılan menfaatın!", Author = "Mehmet Akif Ersoy" },
        };
